INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Cloud immer ein externer Dienst?', 2, '[{"text": "Nein", "correct": true, "because": "Private Cloud ist intern"}, {"text": "Ja", "correct": false, "because": "Nicht nur öffentlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal definiert die Cloud am besten?', 3, '[{"text": "Skalierbarkeit", "correct": true, "because": "Ressourcen nach Bedarf"}, {"text": "Hohe Latenz", "correct": false, "because": "Gegenteil ist Ziel"}, {"text": "Lokale Speicherung", "correct": false, "because": "Nicht cloud-typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Modelle gehören zur Cloud?', 5, '[{"text": "IaaS", "correct": true, "because": "Infrastruktur als Dienst"}, {"text": "PaaS", "correct": true, "because": "Plattform als Dienst"}, {"text": "FTP", "correct": false, "because": "Protokoll, kein Modell"}, {"text": "VPN", "correct": false, "because": "Netzwerktechnik"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Cloud spart lokale Hardware. b) Sie ist immer sicherer als On-Premise.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit hängt ab"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines Cloud-Dienstes?', 4, '[{"text": "Verfügbarkeit", "correct": false, "because": "Kritisch für Betrieb"}, {"text": "Sicherheitsstandards", "correct": false, "because": "Datenschutz essenziell"}, {"text": "Farbe der Server", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Cloud auch offline funktioniert?', 2, '[{"text": "Nein", "correct": true, "because": "Netzwerkzugang nötig"}, {"text": "Ja", "correct": false, "because": "Nur bei lokaler Kopie"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie nutzt die Cloud oft?', 3, '[{"text": "Virtualisierung", "correct": true, "because": "Ressourcen teilen"}, {"text": "Bluetooth", "correct": false, "because": "Kurzreichweite"}, {"text": "USB", "correct": false, "because": "Lokalgeräte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Cloud?', 5, '[{"text": "Kosteneffizienz", "correct": true, "because": "Pay-as-you-go"}, {"text": "Flexibilität", "correct": true, "because": "Skalierbar nach Bedarf"}, {"text": "Höhere Taktfrequenz", "correct": false, "because": "Hardware-spezifisch"}, {"text": "Lokale Installation", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Die Cloud ist immer öffentlich. b) Sie reduziert Wartungsaufwand. Stimmt das?', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Private Cloud existiert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Cloud?', 4, '[{"text": "Internetverbindung", "correct": false, "because": "Zugriff erforderlich"}, {"text": "Service-Provider", "correct": false, "because": "Dienst bereitgestellt"}, {"text": "Lokale Serverräume", "correct": true, "because": "Cloud ersetzt sie"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Cloud nur für große Firmen?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMUs nutzen sie"}, {"text": "Ja", "correct": false, "because": "Skalierbar für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es in der Cloud?', 4, '[{"text": "Datenverlust", "correct": true, "because": "Provider-Ausfall möglich"}, {"text": "Compliance-Probleme", "correct": true, "because": "Datenschutzgesetze"}, {"text": "Langsamer RAM", "correct": false, "because": "Hardware-unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass die Cloud immer teurer ist als On-Premise. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Kostet je nach Nutzung"}, {"text": "Ja", "correct": false, "because": "Flexibel kalkulierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Cloud?', 3, '[{"text": "Sicherheit", "correct": true, "because": "Datenschutz entscheidend"}, {"text": "Lokale Speichergröße", "correct": false, "because": "Cloud ersetzt sie"}, {"text": "Installationzeit", "correct": false, "because": "Schnell bereitgestellt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Cloud nutzt Virtualisierung. b) Sie ersetzt lokale Backups.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Backups bleiben nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dienste bietet die Cloud?', 5, '[{"text": "Speicher", "correct": true, "because": "Datenablage"}, {"text": "Rechenleistung", "correct": true, "because": "Virtuelle Maschinen"}, {"text": "Hardware-Wartung", "correct": false, "because": "Provider-seitig"}, {"text": "Lokale Installation", "correct": false, "because": "Nicht cloud-typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Cloud unwichtig?', 3, '[{"text": "SLA-Verfügbarkeit", "correct": false, "because": "Definiert Zuverlässigkeit"}, {"text": "Datensicherung", "correct": false, "because": "Risikoabsicherung"}, {"text": "Monitorgröße", "correct": true, "because": "Client-seitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Cloud dasselbe wie ein Serverraum?', 2, '[{"text": "Nein", "correct": true, "because": "Cloud ist verteilt"}, {"text": "Ja", "correct": false, "because": "Physikalisch unterschiedlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Cloud auch für Backups geeignet ist?', 2, '[{"text": "Ja", "correct": true, "because": "Speicherlösung"}, {"text": "Nein", "correct": false, "because": "Häufig genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Standard nutzt die Cloud oft?', 4, '[{"text": "REST-API", "correct": true, "because": "Für Dienstzugriff"}, {"text": "SATA", "correct": false, "because": "Hardware-spezifisch"}, {"text": "USB", "correct": false, "because": "Lokalgeräte"}]');
